function(container, apiUrl, tables) {
  const ITEMS_PER_PAGE = 20;
  let currentPage = 1;
  let filteredData = [];
  let allUsers = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const users = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (users) {
        allUsers = users;
        const userSelect = container.querySelector('#filter-user');
        userSelect.innerHTML = '<option value="">全ユーザー</option>';
        users.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 操作履歴テーブルの再描画
  function renderRows(rows) {
    const tbody = container.querySelector('#history-tbody');
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    const endIndex = startIndex + ITEMS_PER_PAGE;
    const pageRows = rows.slice(startIndex, endIndex);

    tbody.innerHTML = pageRows.map(row => {
      const user = allUsers.find(u => u.ユーザーID === row.ユーザーID);
      const userName = user ? user.ユーザー名 : row.ユーザーID || '';
      const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';
      const processingTime = row.処理時間 ? `${row.処理時間}ms` : '';

      return `
        <tr data-id="${row.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${userName}</td>
          <td>${row.操作種別 || ''}</td>
          <td>${row.操作画面 || ''}</td>
          <td>${row.IPアドレス || ''}</td>
          <td><span class="status-badge ${getResultClass(row.処理結果)}">${row.処理結果 || ''}</span></td>
          <td>${processingTime}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updatePagination(rows.length);
    updateResultsInfo(rows.length);
  }

  function getResultClass(result) {
    switch(result) {
      case '成功': return 'success';
      case '失敗': return 'error';
      case 'エラー': return 'error';
      default: return '';
    }
  }

  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / ITEMS_PER_PAGE);
    const pageInfo = container.querySelector('#page-info');
    const prevBtn = container.querySelector('#btn-prev');
    const nextBtn = container.querySelector('#btn-next');

    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    prevBtn.disabled = currentPage <= 1;
    nextBtn.disabled = currentPage >= totalPages;
  }

  function updateResultsInfo(totalItems) {
    const info = container.querySelector('#search-results-info');
    info.textContent = `${totalItems}件の操作履歴が見つかりました`;
  }

  // フィルタリング処理
  async function applyFilters() {
    try {
      const allRows = await window.aivicApi.list(12); // システム操作履歴テーブル
      if (!allRows) return;

      const startDate = container.querySelector('#filter-start-date').value;
      const endDate = container.querySelector('#filter-end-date').value;
      const userId = container.querySelector('#filter-user').value;
      const operationType = container.querySelector('#filter-operation-type').value;
      const screenName = container.querySelector('#filter-screen-name').value.toLowerCase();
      const ipAddress = container.querySelector('#filter-ip-address').value.toLowerCase();
      const result = container.querySelector('#filter-result').value;

      // 日付範囲バリデーション
      if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
        alert('開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。');
        return;
      }

      // IPアドレス形式バリデーション
      if (ipAddress && !isValidIpAddress(ipAddress)) {
        alert('不正なIPアドレス形式です。正しい形式で入力してください。');
        return;
      }

      filteredData = allRows.filter(row => {
        // 日付範囲フィルター
        if (startDate || endDate) {
          const rowDate = row.操作日時 ? new Date(row.操作日時).toISOString().split('T')[0] : '';
          if (startDate && rowDate < startDate) return false;
          if (endDate && rowDate > endDate) return false;
        }

        // ユーザーフィルター
        if (userId && row.ユーザーID !== userId) return false;

        // 操作種別フィルター
        if (operationType && row.操作種別 !== operationType) return false;

        // 画面名フィルター
        if (screenName && !(row.操作画面 || '').toLowerCase().includes(screenName)) return false;

        // IPアドレスフィルター
        if (ipAddress && !(row.IPアドレス || '').toLowerCase().includes(ipAddress)) return false;

        // 処理結果フィルター
        if (result && row.処理結果 !== result) return false;

        return true;
      });

      currentPage = 1;
      renderRows(filteredData);

      if (filteredData.length === 0) {
        container.querySelector('#search-results-info').textContent = '該当する操作履歴が見つかりませんでした';
      }
    } catch (error) {
      console.error('検索処理でエラーが発生しました:', error);
      alert('検索処理でエラーが発生しました');
    }
  }

  function isValidIpAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip);
  }

  // 検索条件クリア
  function clearFilters() {
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#filter-user').value = '';
    container.querySelector('#filter-operation-type').value = '';
    container.querySelector('#filter-screen-name').value = '';
    container.querySelector('#filter-ip-address').value = '';
    container.querySelector('#filter-result').value = '';

    currentPage = 1;
    applyFilters();
  }

  // CSV出力
  async function exportToCsv() {
    try {
      const allRows = await window.aivicApi.list(12);
      if (!allRows || allRows.length === 0) {
        alert('出力するデータがありません');
        return;
      }

      // 大量データの場合の警告
      if (allRows.length > 100000) {
        alert('データ量が多すぎるため、CSV出力に失敗しました。検索条件を絞り込んでから再度お試しください。');
        return;
      }

      const headers = ['操作日時', 'ユーザーID', 'ユーザー名', '操作種別', '操作画面', '操作対象テーブル', '操作対象ID', '操作内容', 'IPアドレス', 'ユーザーエージェント', '処理結果', 'エラーメッセージ', '処理時間'];

      const csvContent = [
        headers.join(','),
        ...allRows.map(row => {
          const user = allUsers.find(u => u.ユーザーID === row.ユーザーID);
          const userName = user ? user.ユーザー名 : '';
          const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';

          return [
            `"${operationDate}"`,
            `"${row.ユーザーID || ''}"`,
            `"${userName}"`,
            `"${row.操作種別 || ''}"`,
            `"${row.操作画面 || ''}"`,
            `"${row.操作対象テーブル || ''}"`,
            `"${row.操作対象ID || ''}"`,
            `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
            `"${row.IPアドレス || ''}"`,
            `"${(row.ユーザーエージェント || '').replace(/"/g, '""')}"`,
            `"${row.処理結果 || ''}"`,
            `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`,
            `"${row.処理時間 || ''}"`
          ].join(',');
        })
      ].join('\n');

      const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `システム操作履歴_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSV出力でエラーが発生しました:', error);
      alert('CSV出力でエラーが発生しました');
    }
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = filteredData.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const user = allUsers.find(u => u.ユーザーID === history.ユーザーID);
    const userName = user ? user.ユーザー名 : history.ユーザーID || '';
    const operationDate = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';

    container.querySelector('#detail-datetime').textContent = operationDate;
    container.querySelector('#detail-user').textContent = userName;
    container.querySelector('#detail-operation-type').textContent = history.操作種別 || '';
    container.querySelector('#detail-screen').textContent = history.操作画面 || '';
    container.querySelector('#detail-target-table').textContent = history.操作対象テーブル || '';
    container.querySelector('#detail-target-id').textContent = history.操作対象ID || '';
    container.querySelector('#detail-ip').textContent = history.IPアドレス || '';
    container.querySelector('#detail-user-agent').textContent = history.ユーザーエージェント || '';
    container.querySelector('#detail-result').textContent = history.処理結果 || '';
    container.querySelector('#detail-processing-time').textContent = history.処理時間 ? `${history.処理時間}ms` : '';
    container.querySelector('#detail-content').textContent = history.操作内容 || '';
    container.querySelector('#detail-error').textContent = history.エラーメッセージ || '';

    container.querySelector('#detail-modal').classList.remove('hidden');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    await loadUsers();
    await applyFilters();
  }

  // イベントリスナー登録
  container.querySelector('#btn-search').addEventListener('click', applyFilters);
  container.querySelector('#btn-clear').addEventListener('click', clearFilters);
  container.querySelector('#btn-csv-export').addEventListener('click', exportToCsv);

  // ページネーション
  container.querySelector('#btn-prev').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredData);
    }
  });

  container.querySelector('#btn-next').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredData.length / ITEMS_PER_PAGE);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredData);
    }
  });

  // モーダル関連
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target.id === 'detail-modal') {
      container.querySelector('#detail-modal').classList.add('hidden');
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // 初期化
  loadInitialData();
}
